    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long lo;
    long long hi;
    cin >> n >> lo >> hi;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    vector<long long> pre(n + 1, 0);
    for (long long i = 0; i < n; i++) pre[i + 1] = pre[i] + a[i];
