import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static void bitAdd(long[] t, int i, long x) {
        int n = t.length - 1;
        for (; i <= n; i += i & -i) t[i] += x;
    }

    static long bitSum(long[] t, int i) {
        long s = 0;
        for (; i > 0; i -= i & -i) s += t[i];
        return s;
    }

    static int lowerBound(long[] a, long v) {
        int lo = 0, hi = a.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (a[mid] < v) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long lo = Long.parseLong(next());
        long hi = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());

        int cnt = (int) n;
        long[] pre = new long[cnt + 1];
        for (int i = 0; i < cnt; i++) pre[i + 1] = pre[i] + a[i];
        long[] sorted = pre.clone();
        Arrays.sort(sorted);
        int m = 0;
        for (int i = 0; i <= cnt; i++) {
            if (i == 0 || sorted[i] != sorted[i - 1]) sorted[m++] = sorted[i];
        }
        long[] vals = Arrays.copyOf(sorted, m);
        long[] t = new long[m + 1];
        long total = 0;
        for (int v = 0; v <= cnt; v++) {
            int first = lowerBound(vals, pre[v] - hi);
            int last = lowerBound(vals, pre[v] - lo + 1);
            total += bitSum(t, last) - bitSum(t, first);
            bitAdd(t, lowerBound(vals, pre[v]) + 1, 1);
        }
        System.out.println(total);
    }
}
